-- PaperGo schema. Pre-release: edit this file in place; do not add migrations
-- (see AGENTS.md). Ent models the tables and indexes; the FTS tables, the
-- integrity, projection and permission-scope triggers, and the runner's
-- runner_step_results table are SQLite-specific and are not generated by Ent.
-- DBOS Transact creates and migrates its own tables in this file when the
-- runner launches; their names are reserved (docs/workflows.md).

-- Tables
CREATE TABLE identity_preferences (id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, owner_type TEXT NOT NULL CHECK(owner_type IN ('user','organization')), owner_id TEXT NOT NULL CHECK(length(owner_id)<=255 AND (owner_type='user' AND owner_id<>'' OR owner_type='organization' AND owner_id='')), `values` JSON NOT NULL DEFAULT '{}' CHECK(json_valid(`values`) AND json_type(`values`)='object'), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE UNIQUE INDEX identitypreference_owner_type_owner_id ON identity_preferences(owner_type,owner_id);
CREATE TRIGGER identity_preference_owner BEFORE INSERT ON identity_preferences WHEN new.owner_type='user' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM identity_users WHERE id=new.owner_id) THEN RAISE(ABORT,'preferences require an enrolled user') END;
END;
CREATE TRIGGER identity_preference_owner_immutable BEFORE UPDATE OF owner_type,owner_id ON identity_preferences BEGIN
 SELECT RAISE(ABORT,'preference owner is immutable');
END;

CREATE TABLE `audit_events` (`id` text NOT NULL, `created_at` datetime NOT NULL, `workspace_id` text NULL, `resource_id` text NULL, `subject` text NOT NULL, `action` text NOT NULL, entity_type TEXT NOT NULL CHECK(length(entity_type)>0), entity_id TEXT NULL, properties JSON NOT NULL DEFAULT '[]' CHECK(json_valid(properties) AND json_type(properties)='array'), trace_id TEXT NOT NULL CHECK(length(trace_id)>0), `details` json NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `blobs` (`id` text NOT NULL, `created_at` datetime NOT NULL, `version` integer NOT NULL, `object_key` text NOT NULL, `filename` text NOT NULL, `content_type` text NOT NULL CHECK(content_type IN ('application/pdf','image/tiff','image/jpeg','image/png','image/webp')), languages TEXT NOT NULL DEFAULT '' CHECK(length(languages)<=191), `size` integer NOT NULL, `sha256` text NOT NULL, `item_id` text NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `blobs_resources_blobs` FOREIGN KEY (`item_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION);
CREATE TABLE `field_definitions` (`id` text NOT NULL, `created_at` datetime NOT NULL, `key` text NOT NULL, `label` text NOT NULL, `type` text NOT NULL, `required` bool NOT NULL DEFAULT (false), `choices` json NOT NULL, indexed BOOLEAN NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), index_status TEXT NOT NULL DEFAULT 'ready' CHECK(index_status IN ('ready','building','failed')), scale INTEGER NOT NULL DEFAULT 0, options JSON NOT NULL DEFAULT '{}' CHECK(json_valid(options) AND json_type(options)='object'), PRIMARY KEY (`id`));
CREATE TABLE blob_deletions (id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, object_key TEXT NOT NULL UNIQUE);
CREATE TABLE `grants` (`id` text NOT NULL, `created_at` datetime NOT NULL, `principal_type` text NOT NULL CHECK(principal_type IN ('user','group','workspace_visitor','workspace_member','workspace_owner')), `principal_id` text NOT NULL, `action` text NOT NULL, `effect` text NOT NULL, `resource_id` text NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `grants_resources_grants` FOREIGN KEY (`resource_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION);
CREATE TABLE `publications` (`id` text NOT NULL, `created_at` datetime NOT NULL, `version` integer NOT NULL, `published_by` text NOT NULL, `snapshot` json NOT NULL, `item_id` text NOT NULL, action TEXT NOT NULL DEFAULT 'publish', revision_id TEXT, PRIMARY KEY (`id`), CONSTRAINT `publications_resources_publications` FOREIGN KEY (`item_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION);
CREATE TABLE `relationships` (`id` text NOT NULL, `created_at` datetime NOT NULL, `metadata` json NOT NULL, `source_id` text NOT NULL, `target_id` text NOT NULL, type_id TEXT REFERENCES relationship_types(id), directed BOOLEAN NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), PRIMARY KEY (`id`), CONSTRAINT `relationships_resources_outgoing` FOREIGN KEY (`source_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION, CONSTRAINT `relationships_resources_incoming` FOREIGN KEY (`target_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION);
CREATE TABLE `resources` (`id` text NOT NULL, `created_at` datetime NOT NULL, `workspace_id` text NOT NULL, personal_owner_id TEXT REFERENCES identity_users(id) CHECK(personal_owner_id IS NULL OR kind='workspace'), system_key TEXT CHECK(system_key IS NULL OR (kind='library' AND system_key IN ('home.documents','home.inbox'))), `kind` text NOT NULL, `name` text NOT NULL, `description` text NOT NULL DEFAULT '' CHECK(length(description)<=2000 AND (kind IN ('workspace','list','library') OR description='')), allow_folders BOOLEAN NOT NULL DEFAULT 1 CHECK(allow_folders IN (0,1) AND (kind IN ('list','library') OR allow_folders=1)), `tags` json NOT NULL, `values` json NOT NULL, `inherit_permissions` bool NOT NULL DEFAULT (true), `version` integer NOT NULL DEFAULT (1), `updated_at` datetime NOT NULL, `scope_id` text NULL, `parent_id` text NULL, `container_id` text NULL, head_revision_id TEXT REFERENCES item_revisions(id), published_revision_id TEXT REFERENCES item_revisions(id), schema_head_id TEXT REFERENCES schema_revisions(id), next_revision_number INTEGER NOT NULL DEFAULT 1, publishing_enabled BOOLEAN NOT NULL DEFAULT 0, versioning TEXT NOT NULL DEFAULT 'off' CHECK(versioning IN ('off','major') AND (kind IN ('list','library') OR versioning='off')), max_versions INTEGER NOT NULL DEFAULT 50 CHECK(max_versions BETWEEN 1 AND 500 AND (kind IN ('list','library') OR max_versions=50)), webdav_enabled BOOLEAN NOT NULL DEFAULT 0, duplicate_policy TEXT NOT NULL DEFAULT 'warn' CHECK(duplicate_policy IN ('allow','warn','block') AND (kind='library' OR duplicate_policy='warn')), name_key TEXT NULL, deleted_at DATETIME NULL, deleted_by TEXT NULL, created_by TEXT NOT NULL DEFAULT '', updated_by TEXT NOT NULL DEFAULT '', content_type_id TEXT NULL, template_keys JSON NOT NULL DEFAULT '[]' CHECK(json_valid(template_keys) AND json_type(template_keys)='array' AND json_array_length(template_keys)<=100 AND (kind IN ('list','library') OR json_array_length(template_keys)=0)), PRIMARY KEY (`id`), CONSTRAINT `resources_resources_children` FOREIGN KEY (`parent_id`) REFERENCES `resources` (`id`) ON DELETE SET NULL, CONSTRAINT `resources_resources_contained_items` FOREIGN KEY (`container_id`) REFERENCES `resources` (`id`) ON DELETE SET NULL, CHECK(deleted_at IS NULL OR name_key IS NULL), CHECK((kind IN ('item','folder'))=(content_type_id IS NOT NULL)), FOREIGN KEY(content_type_id) REFERENCES content_types(id));
CREATE TABLE resource_tags (
  resource_id TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE,
  tag TEXT NOT NULL,
  PRIMARY KEY (tag,resource_id)
) WITHOUT ROWID;
CREATE TABLE schema_revisions (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, container_id TEXT NOT NULL REFERENCES resources(id),
 revision_number INTEGER NOT NULL CHECK(revision_number>0), definition JSON NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object'), created_by TEXT NOT NULL
);
CREATE TABLE content_types (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL,
 key TEXT NOT NULL, name TEXT NOT NULL, template_key TEXT NULL,
 field_ids JSON NOT NULL CHECK(json_valid(field_ids) AND json_type(field_ids)='array'),
 rules JSON NOT NULL CHECK(json_valid(rules) AND json_type(rules)='array'),
 version INTEGER NOT NULL DEFAULT 1 CHECK(version>0)
);
CREATE TABLE collection_types (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL,
 container_id TEXT NOT NULL REFERENCES resources(id), content_type_id TEXT NOT NULL REFERENCES content_types(id),
 is_default BOOLEAN NOT NULL DEFAULT 0 CHECK(is_default IN (0,1))
);
CREATE TABLE business_keys (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL,
 container_id TEXT NOT NULL REFERENCES resources(id), item_id TEXT NOT NULL REFERENCES resources(id),
 field_key TEXT NOT NULL, value TEXT NOT NULL
);
CREATE TABLE item_revisions (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL,
 item_id TEXT NOT NULL REFERENCES resources(id), container_id TEXT NOT NULL REFERENCES resources(id),
 schema_revision_id TEXT NOT NULL, content_type_id TEXT NOT NULL, revision_number INTEGER NOT NULL CHECK(revision_number>0),
 name TEXT NOT NULL, tags JSON NOT NULL CHECK(json_valid(tags) AND json_type(tags)='array'), payload JSON NOT NULL CHECK(json_valid(payload) AND json_type(payload)='object'),
 created_by TEXT NOT NULL, blob_id TEXT REFERENCES blobs(id),
 FOREIGN KEY(container_id,schema_revision_id) REFERENCES schema_revisions(container_id,id),
  FOREIGN KEY(content_type_id) REFERENCES content_types(id)
);
CREATE TABLE item_histories (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL,
 revision_id TEXT NOT NULL REFERENCES item_revisions(id),
 item_id TEXT NOT NULL REFERENCES resources(id), number INTEGER NOT NULL CHECK(number>0),
 changed_fields JSON NOT NULL CHECK(json_valid(changed_fields) AND json_type(changed_fields)='array')
);
CREATE UNIQUE INDEX itemhistory_revision_id ON item_histories(revision_id);
CREATE UNIQUE INDEX itemhistory_item_id_number ON item_histories(item_id,number);
CREATE TRIGGER item_history_ownership BEFORE INSERT ON item_histories BEGIN SELECT RAISE(ABORT,'invalid history ownership') WHERE NOT EXISTS(SELECT 1 FROM item_revisions WHERE id=new.revision_id AND item_id=new.item_id);END;
CREATE TRIGGER item_history_immutable BEFORE UPDATE ON item_histories BEGIN SELECT RAISE(ABORT,'item history is immutable'); END;
CREATE TABLE item_surfaces (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, item_id TEXT NOT NULL REFERENCES resources(id),
 container_id TEXT NOT NULL REFERENCES resources(id), workspace_id TEXT NOT NULL,
 surface TEXT NOT NULL CHECK(surface IN ('head','published')), revision_id TEXT NOT NULL,
 name TEXT NOT NULL, tags JSON NOT NULL CHECK(json_valid(tags) AND json_type(tags)='array'), payload JSON NOT NULL CHECK(json_valid(payload) AND json_type(payload)='object'),
 term_text TEXT NOT NULL DEFAULT '',
 item_created_at TEXT NOT NULL, item_created_by TEXT NOT NULL, modified_at TEXT NOT NULL, modified_by TEXT NOT NULL,
 FOREIGN KEY(item_id,revision_id) REFERENCES item_revisions(item_id,id)
);
CREATE TABLE item_surface_tags(surface_id TEXT NOT NULL REFERENCES item_surfaces(id) ON DELETE CASCADE,tag TEXT NOT NULL,PRIMARY KEY(tag,surface_id)) WITHOUT ROWID;
CREATE TABLE "field_values" (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, surface_id TEXT NOT NULL REFERENCES item_surfaces(id),
 container_id TEXT NOT NULL, item_id TEXT NOT NULL, surface TEXT NOT NULL, field_key TEXT NOT NULL, field_type TEXT NOT NULL,
 scale INTEGER NOT NULL DEFAULT 0, ordinal INTEGER NOT NULL DEFAULT 0 CHECK(ordinal>=0),
 value_text TEXT, value_integer INTEGER, value_boolean BOOLEAN,
 CHECK((value_text IS NOT NULL)+(value_integer IS NOT NULL)+(value_boolean IS NOT NULL)=1),
 CHECK((field_type IN ('text','note','email','url','date','lookup','person','term','keywords','choice','datetime') AND value_text IS NOT NULL)
 OR (field_type IN ('integer','decimal') AND value_integer IS NOT NULL)
 OR (field_type IN ('number','currency') AND value_text IS NOT NULL AND length(value_text)=58 AND substr(value_text,1,1) IN ('0','1') AND value_text NOT GLOB '*[^0-9]*')
 OR (field_type='boolean' AND value_boolean IS NOT NULL AND value_boolean IN (0,1))),
 CHECK(scale BETWEEN 0 AND 9 AND (field_type='decimal' OR scale=0)),
 CHECK(value_integer IS NULL OR typeof(value_integer)='integer')
);
CREATE TABLE schema_templates (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,workspace_id TEXT NOT NULL REFERENCES resources(id),
 key TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',definition JSON NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object'),
 version INTEGER NOT NULL DEFAULT 1 CHECK(version>0)
);
CREATE TABLE term_groups (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,
 name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',is_system BOOLEAN NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0)
);
CREATE TABLE term_sets (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,
 group_id TEXT NOT NULL REFERENCES term_groups(id),
 key TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',is_open BOOLEAN NOT NULL DEFAULT 0,is_keywords BOOLEAN NOT NULL DEFAULT 0,
 version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
 CHECK(NOT is_keywords OR is_open)
);
CREATE TABLE terms (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,term_set_id TEXT NOT NULL REFERENCES term_sets(id),
 parent_id TEXT REFERENCES terms(id),name TEXT NOT NULL,normalized_name TEXT NOT NULL,
 labels JSON NOT NULL CHECK(json_valid(labels) AND json_type(labels)='object'),synonyms JSON NOT NULL CHECK(json_valid(synonyms) AND json_type(synonyms)='array'),
 description TEXT NOT NULL DEFAULT '',color TEXT CHECK(color IS NULL OR (length(color)=7 AND color GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]')),
 sort_order INTEGER NOT NULL DEFAULT 0,path TEXT NOT NULL CHECK(path LIKE '/%/'),
 merged_into_id TEXT REFERENCES terms(id),available_as_keyword BOOLEAN NOT NULL DEFAULT 0,
 deprecated BOOLEAN NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
 CHECK(merged_into_id IS NULL OR deprecated), CHECK(merged_into_id IS NOT id)
);
CREATE TABLE list_views (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,container_id TEXT NOT NULL REFERENCES resources(id),
 name TEXT NOT NULL,columns JSON NOT NULL CHECK(json_valid(columns) AND json_type(columns)='array'),
 query JSON NOT NULL CHECK(json_valid(query) AND json_type(query)='object'),layout TEXT NOT NULL DEFAULT 'table' CHECK(layout IN ('table','board','calendar','gallery')),
 is_default BOOLEAN NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0)
);
CREATE TABLE operations (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,container_id TEXT REFERENCES resources(id),
 field_id TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(length(kind) BETWEEN 1 AND 64),
 trace_id TEXT NOT NULL,credential_id TEXT,credential_scopes JSON NOT NULL DEFAULT '[]' CHECK(json_valid(credential_scopes) AND json_type(credential_scopes)='array'),
 result JSON NOT NULL DEFAULT '{}' CHECK(json_valid(result)),started_at DATETIME,completed_at DATETIME,
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','succeeded','failed','superseded')),
 surface TEXT NOT NULL DEFAULT 'head' CHECK(surface IN ('head','published')),after_item_id TEXT NOT NULL DEFAULT '',
 processed INTEGER NOT NULL DEFAULT 0 CHECK(processed>=0),error TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL,
 payload JSON NOT NULL DEFAULT '{}' CHECK(json_valid(payload) AND json_type(payload)='object'),prepared BOOLEAN NOT NULL DEFAULT 0,
 matched INTEGER NOT NULL DEFAULT 0 CHECK(matched>=0),updated INTEGER NOT NULL DEFAULT 0 CHECK(updated>=0),failed INTEGER NOT NULL DEFAULT 0 CHECK(failed>=0),
 progress INTEGER NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),failures JSON NOT NULL DEFAULT '[]' CHECK(json_valid(failures) AND json_type(failures)='array')
);
CREATE TABLE operation_items (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,
 operation_id TEXT NOT NULL REFERENCES operations(id) ON DELETE CASCADE,item_id TEXT NOT NULL REFERENCES resources(id)
);
CREATE UNIQUE INDEX operationitem_operation_id_item_id ON operation_items(operation_id,item_id);
CREATE TABLE webdav_credentials (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,subject TEXT NOT NULL,label TEXT NOT NULL,
 secret_hash TEXT NOT NULL CHECK(length(secret_hash)=64),expires_at DATETIME
);
CREATE TABLE smart_folders (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL,
 workspace_id TEXT REFERENCES resources(id), owner_id TEXT,
 name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
 definition JSON NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object'),
 created_by TEXT NOT NULL, updated_by TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
 CHECK(workspace_id IS NOT NULL OR owner_id IS NOT NULL), CHECK(owner_id IS NULL OR length(owner_id)>0)
);
CREATE TABLE relationship_types (
 id TEXT PRIMARY KEY NOT NULL REFERENCES terms(id),created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,
 inverse_label TEXT NOT NULL DEFAULT '',directed BOOLEAN NOT NULL DEFAULT 0,
 max_incoming INTEGER CHECK(max_incoming BETWEEN 1 AND 1000),max_outgoing INTEGER CHECK(max_outgoing BETWEEN 1 AND 1000),
 attributes JSON NOT NULL CHECK(json_valid(attributes) AND json_type(attributes)='object'),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
 CHECK(directed OR (inverse_label='' AND max_incoming IS NULL AND max_outgoing IS NULL))
);

CREATE TABLE domain_events (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, type TEXT NOT NULL,
 workspace_id TEXT NOT NULL, collection_id TEXT, resource_id TEXT, actor TEXT NOT NULL,
 data JSON NOT NULL DEFAULT '{}' CHECK(json_valid(data) AND json_type(data)='object'),
 depth INTEGER NOT NULL CHECK(depth>=0), cause_run_id TEXT, dispatched_at DATETIME
);
CREATE TABLE workflows (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL,
 workspace_id TEXT NOT NULL REFERENCES resources(id), key TEXT NOT NULL CHECK(length(key) BETWEEN 1 AND 100),
 name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', enabled BOOLEAN NOT NULL DEFAULT 1,
 builtin_key TEXT, collection_id TEXT REFERENCES resources(id),
 parameters JSON NOT NULL DEFAULT '{}' CHECK(json_valid(parameters) AND json_type(parameters)='object'),
 current_version INTEGER NOT NULL CHECK(current_version>0),
 created_by TEXT NOT NULL, updated_by TEXT NOT NULL, deleted_at DATETIME,
 version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
 CHECK(collection_id IS NULL OR builtin_key IS NOT NULL)
);
CREATE TABLE workflow_versions (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, workflow_id TEXT NOT NULL REFERENCES workflows(id),
 number INTEGER NOT NULL CHECK(number>0), definition JSON NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object'),
 created_by TEXT NOT NULL
);
CREATE TABLE workflow_triggers (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, workflow_id TEXT NOT NULL REFERENCES workflows(id),
 workspace_id TEXT NOT NULL REFERENCES resources(id), collection_id TEXT REFERENCES resources(id),
 type TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0), next_at DATETIME,
 CHECK((type='schedule')=(next_at IS NOT NULL))
);
CREATE TABLE workflow_runs (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, workflow_id TEXT NOT NULL REFERENCES workflows(id),
 workflow_version INTEGER NOT NULL CHECK(workflow_version>0), workspace_id TEXT NOT NULL REFERENCES resources(id),
 item_id TEXT, event_id TEXT NOT NULL, event_type TEXT NOT NULL,
 depth INTEGER NOT NULL CHECK(depth>=0), actor TEXT NOT NULL, retry_of TEXT
,
 live_status TEXT NOT NULL DEFAULT 'queued',live_updated_at INTEGER NOT NULL DEFAULT 0 CHECK(live_updated_at>=0)
);
CREATE TABLE workflow_run_items (
 id TEXT PRIMARY KEY NOT NULL, run_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE,
 item_id TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0)
);
CREATE TABLE staged_files (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,
 workspace_id TEXT NOT NULL,item_id TEXT NOT NULL,run_id TEXT NOT NULL,
 sources JSON NOT NULL CHECK(json_valid(sources) AND json_type(sources)='array'),
 object_key TEXT NOT NULL CHECK(object_key<>''),filename TEXT NOT NULL CHECK(length(filename) BETWEEN 1 AND 255),
 content_type TEXT NOT NULL CHECK(length(content_type) BETWEEN 1 AND 255),size INTEGER NOT NULL CHECK(size>=0),sha256 TEXT NOT NULL,
 metrics JSON NOT NULL DEFAULT '{}' CHECK(json_valid(metrics)),
 state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','promoted','discarded')),created_by TEXT NOT NULL
);
CREATE TABLE tasks (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
 workspace_id TEXT NOT NULL,item_id TEXT,kind TEXT NOT NULL DEFAULT 'task' CHECK(kind IN ('task','approval')),key TEXT NOT NULL DEFAULT '' CHECK(length(key)<=64),
 title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 500),description TEXT NOT NULL DEFAULT '' CHECK(length(description)<=4000),
 assignees JSON NOT NULL CHECK(json_valid(assignees) AND json_type(assignees)='array'),
 completion TEXT NOT NULL DEFAULT 'any' CHECK(completion IN ('any','all')),
 outcomes JSON NOT NULL CHECK(json_valid(outcomes) AND json_type(outcomes)='array' AND json_array_length(outcomes)>0),
 input_schema JSON CHECK(input_schema IS NULL OR json_valid(input_schema)),`values` JSON CHECK(`values` IS NULL OR json_valid(`values`)),
 review JSON CHECK(review IS NULL OR json_valid(review)),
 priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')),due_at DATETIME,
 source TEXT NOT NULL CHECK(source IN ('workflow','user','system')),workflow_id TEXT,run_id TEXT,node TEXT,
 wait BOOLEAN NOT NULL DEFAULT 0,parked BOOLEAN NOT NULL DEFAULT 0,
 status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','completed','cancelled','expired')),
 outcome TEXT,completed_by TEXT,completed_at DATETIME,comment TEXT NOT NULL DEFAULT '' CHECK(length(comment)<=4000),
 input JSON CHECK(input IS NULL OR json_valid(input)),created_by TEXT NOT NULL,
 CHECK(source<>'workflow' OR (workflow_id IS NOT NULL AND run_id IS NOT NULL AND node IS NOT NULL)),
 CHECK((status='open')=(completed_at IS NULL))
);
CREATE TABLE task_responses (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
 subject TEXT NOT NULL,assignee TEXT NOT NULL,outcome TEXT NOT NULL,comment TEXT NOT NULL DEFAULT '' CHECK(length(comment)<=4000),
 input JSON CHECK(input IS NULL OR json_valid(input))
);
CREATE TABLE runner_step_results (
 run_id TEXT NOT NULL, step_id INTEGER NOT NULL, step TEXT NOT NULL, output BLOB NOT NULL,
 PRIMARY KEY (run_id, step_id)
) WITHOUT ROWID;

-- Full-text search over resources and item surfaces (external content)
CREATE VIRTUAL TABLE resource_search USING fts5(
  id UNINDEXED, name, tags, "values",
  content='resources', content_rowid='rowid', tokenize='unicode61'
);
CREATE VIRTUAL TABLE item_surface_search USING fts5(id UNINDEXED,name,tags,payload,term_text,content='item_surfaces',content_rowid='rowid',tokenize='unicode61');

-- Indexes
CREATE INDEX `auditevent_workspace_id_created_at` ON `audit_events` (`workspace_id`, `created_at`);
CREATE INDEX `auditevent_resource_id_created_at` ON `audit_events` (`resource_id`, `created_at`);
CREATE INDEX `blob_sha256_item_id` ON `blobs` (`sha256`, `item_id`);
CREATE INDEX `blob_object_key` ON `blobs` (`object_key`);
CREATE UNIQUE INDEX `blob_item_id_version` ON `blobs` (`item_id`, `version`);
CREATE INDEX fielddefinition_key ON field_definitions(key);
CREATE UNIQUE INDEX `grant_resource_id_principal_type_principal_id_action` ON `grants` (`resource_id`, `principal_type`, `principal_id`, `action`);
CREATE INDEX `grant_principal_type_principal_id_resource_id` ON `grants` (`principal_type`, `principal_id`, `resource_id`);
CREATE INDEX `relationship_source_id_type_id_id` ON `relationships` (`source_id`, `type_id`, `id`);
CREATE INDEX `relationship_target_id_type_id_id` ON `relationships` (`target_id`, `type_id`, `id`);
CREATE INDEX `resource_workspace_id_kind_id` ON `resources` (`workspace_id`, `kind`, `id`);
CREATE INDEX resource_kind_id_workspace_id_scope_id ON resources(kind,id,workspace_id,scope_id);
CREATE INDEX smartfolder_owner_id_id ON smart_folders(owner_id,id);
CREATE INDEX smartfolder_workspace_id_id ON smart_folders(workspace_id,id);
CREATE UNIQUE INDEX smartfolder_workspace_id_name ON smart_folders(workspace_id,name) WHERE owner_id IS NULL;
CREATE UNIQUE INDEX smartfolder_owner_id_workspace_id_name ON smart_folders(owner_id,workspace_id,name);
CREATE UNIQUE INDEX smartfolder_owner_id_name ON smart_folders(owner_id,name) WHERE workspace_id IS NULL;
CREATE INDEX `resource_parent_id_id_scope_id` ON `resources` (`parent_id`, `id`, `scope_id`);
CREATE INDEX `resource_parent_id_kind_id_scope_id` ON `resources` (`parent_id`, `kind`, `id`, `scope_id`);
CREATE INDEX `resource_container_id_id` ON `resources` (`container_id`, `id`);
CREATE INDEX resource_container_id_content_type_id_id ON resources(container_id,content_type_id,id);
CREATE INDEX resource_container_id_scope_id ON resources(container_id,scope_id);
CREATE INDEX contenttype_key ON content_types(key);
CREATE UNIQUE INDEX contenttype_template_key ON content_types(template_key);
CREATE UNIQUE INDEX collectiontype_container_id_content_type_id ON collection_types(container_id,content_type_id);
CREATE INDEX collectiontype_content_type_id_container_id ON collection_types(content_type_id,container_id);
CREATE UNIQUE INDEX collectiontype_container_id ON collection_types(container_id) WHERE is_default=1;
CREATE UNIQUE INDEX businesskey_container_id_field_key_value ON business_keys(container_id,field_key,value);
CREATE INDEX businesskey_item_id ON business_keys(item_id);
CREATE INDEX resource_tags_by_resource ON resource_tags(resource_id,tag);
CREATE INDEX resource_workspace_id_id_scope_id ON resources(workspace_id,id,scope_id);
CREATE UNIQUE INDEX resource_parent_id_name_key ON resources(parent_id,name_key) WHERE name_key IS NOT NULL;
CREATE INDEX resource_head_revision_id ON resources(head_revision_id) WHERE head_revision_id IS NOT NULL;
CREATE INDEX resource_published_revision_id ON resources(published_revision_id) WHERE published_revision_id IS NOT NULL;
CREATE INDEX resource_container_id_deleted_at_id ON resources(container_id,deleted_at,id) WHERE deleted_at IS NOT NULL;
CREATE UNIQUE INDEX webdav_credentials_secret_hash_key ON webdav_credentials(secret_hash);
CREATE INDEX webdavcredential_subject_id ON webdav_credentials(subject,id);
CREATE INDEX relationship_source_id_id ON relationships(source_id,id);
CREATE INDEX relationship_target_id_id ON relationships(target_id,id);
