-- Triggers: derived projections, integrity guards and permission scopes
CREATE TRIGGER resource_search_insert AFTER INSERT ON resources BEGIN
  INSERT INTO resource_search(rowid,id,name,tags,"values")
    VALUES (new.rowid,new.id,new.name,new.tags,new."values");
END;
CREATE TRIGGER resource_search_delete AFTER DELETE ON resources BEGIN
  INSERT INTO resource_search(resource_search,rowid,id,name,tags,"values")
    VALUES ('delete',old.rowid,old.id,old.name,old.tags,old."values");
END;
-- Search rows depend only on name, tags and values, not version bumps or scope maintenance.
CREATE TRIGGER resource_search_update AFTER UPDATE OF name,tags,"values" ON resources BEGIN
  INSERT INTO resource_search(resource_search,rowid,id,name,tags,"values")
    VALUES ('delete',old.rowid,old.id,old.name,old.tags,old."values");
  INSERT INTO resource_search(rowid,id,name,tags,"values")
    VALUES (new.rowid,new.id,new.name,new.tags,new."values");
END;
-- scope_id is the nearest exclusive ACL scope (ancestor-or-self), so permission
-- checks are one indexed lookup. Triggers own it; the API never writes it.
-- A scope changes on insert, when a resource breaks or resets inheritance, or
-- when an inheriting resource moves; then every descendant reached through
-- inheriting resources follows it, while nested exclusive scopes keep their own.
CREATE TRIGGER resource_scope_insert AFTER INSERT ON resources BEGIN
  UPDATE resources SET scope_id=CASE WHEN new.inherit_permissions THEN (SELECT p.scope_id FROM resources p WHERE p.id=new.parent_id) ELSE new.id END
   WHERE id=new.id;
END;
CREATE TRIGGER resource_scope_move AFTER UPDATE OF parent_id ON resources WHEN new.inherit_permissions AND new.parent_id IS NOT old.parent_id BEGIN
  UPDATE resources SET scope_id=(SELECT p.scope_id FROM resources p WHERE p.id=new.parent_id)
   WHERE id IN (WITH RECURSIVE sub(id) AS (
    SELECT new.id UNION ALL SELECT c.id FROM resources c JOIN sub ON c.parent_id=sub.id WHERE c.inherit_permissions
   ) SELECT id FROM sub);
END;
CREATE TRIGGER resource_scope_inheritance AFTER UPDATE OF inherit_permissions ON resources WHEN old.inherit_permissions IS NOT new.inherit_permissions BEGIN
  UPDATE resources SET scope_id=CASE WHEN new.inherit_permissions THEN (SELECT p.scope_id FROM resources p WHERE p.id=new.parent_id) ELSE new.id END
   WHERE id IN (WITH RECURSIVE sub(id) AS (
    SELECT new.id UNION ALL SELECT c.id FROM resources c JOIN sub ON c.parent_id=sub.id WHERE c.inherit_permissions
   ) SELECT id FROM sub);
END;
CREATE TRIGGER resource_tags_insert AFTER INSERT ON resources BEGIN
  INSERT INTO resource_tags(resource_id,tag) SELECT new.id,value FROM json_each(new.tags);
END;
CREATE TRIGGER resource_tags_update AFTER UPDATE OF tags ON resources BEGIN
  DELETE FROM resource_tags WHERE resource_id=old.id;
  INSERT INTO resource_tags(resource_id,tag) SELECT new.id,value FROM json_each(new.tags);
END;
CREATE TRIGGER resource_validate_insert BEFORE INSERT ON resources BEGIN
  SELECT CASE WHEN new.kind IN ('item','folder') AND NOT EXISTS(SELECT 1 FROM collection_types WHERE container_id=new.container_id AND content_type_id=new.content_type_id) THEN RAISE(ABORT,'content type must be attached to its collection') END;
  SELECT CASE WHEN new.kind='folder' AND EXISTS (SELECT 1 FROM resources c WHERE c.id=new.container_id AND c.allow_folders=0) THEN RAISE(ABORT,'collection does not allow new folders') END;
  SELECT CASE WHEN new.kind='workspace' AND
    (new.workspace_id<>new.id OR new.parent_id IS NOT NULL OR new.container_id IS NOT NULL OR new.inherit_permissions<>0)
    THEN RAISE(ABORT,'invalid workspace') END;
  SELECT CASE WHEN new.kind<>'workspace' AND NOT EXISTS (
    SELECT 1 FROM resources p WHERE p.id=new.parent_id AND p.workspace_id=new.workspace_id
      AND ((new.kind IN ('list','library') AND p.kind='workspace' AND new.container_id IS NULL)
        OR (new.kind IN ('folder','item') AND (
          (p.kind IN ('list','library') AND new.container_id=p.id)
          OR (p.kind='folder' AND new.container_id=p.container_id))))
  ) THEN RAISE(ABORT,'invalid containment') END;
END;
CREATE TRIGGER resource_immutable_ownership BEFORE UPDATE OF id,workspace_id,container_id,kind,content_type_id ON resources BEGIN
  SELECT CASE WHEN new.id IS NOT old.id OR new.kind IS NOT old.kind
    OR (new.kind<>'item' AND (new.workspace_id IS NOT old.workspace_id OR new.container_id IS NOT old.container_id))
    THEN RAISE(ABORT,'resource ownership is immutable') END;
END;
CREATE TRIGGER resource_content_type_validate BEFORE UPDATE OF content_type_id,container_id,deleted_at ON resources WHEN new.kind IN ('item','folder') AND new.deleted_at IS NULL BEGIN
  SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM collection_types WHERE container_id=new.container_id AND content_type_id=new.content_type_id)
  THEN RAISE(ABORT,'content type must be attached to its collection') END;
END;
-- Items may move to compatible collections. Folder trees remain in their collection.
CREATE TRIGGER resource_validate_move BEFORE UPDATE OF parent_id,workspace_id,container_id ON resources WHEN new.parent_id IS NOT old.parent_id OR new.workspace_id IS NOT old.workspace_id OR new.container_id IS NOT old.container_id BEGIN
  SELECT CASE WHEN new.kind NOT IN ('folder','item') OR new.deleted_at IS NOT NULL OR NOT EXISTS (
    SELECT 1 FROM resources p WHERE p.id=new.parent_id AND p.workspace_id=new.workspace_id AND p.deleted_at IS NULL
      AND ((p.kind IN ('list','library') AND p.id=new.container_id) OR (p.kind='folder' AND p.container_id=new.container_id))
  ) THEN RAISE(ABORT,'invalid containment') END;
  SELECT CASE WHEN new.container_id IS NOT old.container_id AND NOT EXISTS (
    SELECT 1 FROM resources src JOIN resources dst ON dst.id=new.container_id
    WHERE src.id=old.container_id AND src.kind=dst.kind AND dst.deleted_at IS NULL AND new.kind='item'
  ) THEN RAISE(ABORT,'cross-collection moves require compatible item collections') END;
  SELECT CASE WHEN EXISTS (WITH RECURSIVE up(id) AS (
    SELECT new.parent_id UNION ALL SELECT r.parent_id FROM resources r JOIN up ON r.id=up.id WHERE r.parent_id IS NOT NULL
  ) SELECT 1 FROM up WHERE id=new.id) THEN RAISE(ABORT,'resource cannot move below itself') END;
END;
-- Deleted content can be restored; tombstones otherwise reject content edits.
CREATE TRIGGER resource_tombstone BEFORE UPDATE ON resources WHEN old.deleted_at IS NOT NULL AND new.deleted_at IS NOT NULL BEGIN
  SELECT CASE WHEN new.deleted_at IS NOT old.deleted_at OR new.parent_id IS NOT old.parent_id OR new.name IS NOT old.name OR new.description IS NOT old.description OR new.name_key IS NOT NULL
    THEN RAISE(ABORT,'deleted resources are retained') END;
END;
CREATE TRIGGER resource_delete_validate BEFORE UPDATE OF deleted_at ON resources WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN
  SELECT CASE WHEN new.kind NOT IN ('workspace','list','library','folder','item') THEN RAISE(ABORT,'invalid deletion kind') END;
END;
CREATE TRIGGER resource_restore_validate BEFORE UPDATE OF deleted_at ON resources WHEN old.deleted_at IS NOT NULL AND new.deleted_at IS NULL BEGIN
  SELECT CASE WHEN new.kind NOT IN ('folder','item') OR NOT EXISTS (
    SELECT 1 FROM resources p JOIN resources c ON c.id=new.container_id JOIN resources w ON w.id=new.workspace_id
    WHERE p.id=new.parent_id AND p.deleted_at IS NULL AND c.deleted_at IS NULL AND w.deleted_at IS NULL
      AND p.workspace_id=new.workspace_id AND ((p.kind IN ('list','library') AND p.id=c.id) OR (p.kind='folder' AND p.container_id=c.id))
  ) THEN RAISE(ABORT,'restore requires a live collection and parent') END;
END;
CREATE TRIGGER webdav_credential_immutable BEFORE UPDATE ON webdav_credentials BEGIN SELECT RAISE(ABORT,'credentials are immutable; revoke and create another'); END;
CREATE TRIGGER smart_folder_workspace BEFORE INSERT ON smart_folders BEGIN
 SELECT CASE WHEN new.workspace_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM resources WHERE id=new.workspace_id AND kind='workspace') THEN RAISE(ABORT,'smart folders require a workspace') END;
END;
CREATE TRIGGER smart_folder_identity BEFORE UPDATE OF id,workspace_id,owner_id,created_by ON smart_folders BEGIN
 SELECT CASE WHEN new.id IS NOT old.id OR new.workspace_id IS NOT old.workspace_id OR new.owner_id IS NOT old.owner_id OR new.created_by IS NOT old.created_by THEN RAISE(ABORT,'smart folder ownership is immutable') END;
END;
CREATE TRIGGER relationship_validate_insert BEFORE INSERT ON relationships BEGIN
  SELECT CASE WHEN new.source_id=new.target_id OR NOT EXISTS (
    SELECT 1 FROM resources s JOIN resources t ON t.id=new.target_id
    WHERE s.id=new.source_id AND s.kind='item' AND t.kind='item'
      AND s.deleted_at IS NULL AND t.deleted_at IS NULL
  ) THEN RAISE(ABORT,'invalid relationship endpoints') END;
END;
CREATE TRIGGER relationship_immutable_endpoints BEFORE UPDATE OF source_id,target_id ON relationships BEGIN
  SELECT CASE WHEN new.source_id IS NOT old.source_id OR new.target_id IS NOT old.target_id
    THEN RAISE(ABORT,'relationship endpoints are immutable') END;
END;
CREATE TRIGGER publication_item_validate BEFORE INSERT ON publications BEGIN
  SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM resources WHERE id=new.item_id AND kind='item')
    THEN RAISE(ABORT,'publication requires item') END;
END;
CREATE TRIGGER blob_item_validate BEFORE INSERT ON blobs BEGIN
  SELECT CASE WHEN EXISTS (SELECT 1 FROM blobs WHERE object_key=new.object_key
    AND (sha256<>new.sha256 OR size<>new.size))
    THEN RAISE(ABORT,'shared blob object must have identical bytes') END;
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM resources i JOIN resources c ON c.id=i.container_id
    WHERE i.id=new.item_id AND i.kind='item' AND c.kind='library'
  ) THEN RAISE(ABORT,'blob requires library item') END;
END;
CREATE TRIGGER blob_immutable BEFORE UPDATE ON blobs BEGIN
  SELECT RAISE(ABORT,'blob revisions are immutable');
END;
CREATE TRIGGER audit_immutable BEFORE UPDATE ON audit_events BEGIN
  SELECT RAISE(ABORT,'audit events are immutable');
END;
CREATE TRIGGER audit_retained BEFORE DELETE ON audit_events BEGIN
  SELECT RAISE(ABORT,'audit events are retained');
END;
CREATE TRIGGER publication_immutable BEFORE UPDATE ON publications BEGIN SELECT RAISE(ABORT,'publication snapshots are immutable'); END;
CREATE TRIGGER item_surface_search_insert AFTER INSERT ON item_surfaces BEGIN
 INSERT INTO item_surface_search(rowid,id,name,tags,payload,term_text) VALUES(new.rowid,new.id,new.name,new.tags,new.payload,new.term_text);
END;
CREATE TRIGGER item_surface_search_delete AFTER DELETE ON item_surfaces BEGIN
 INSERT INTO item_surface_search(item_surface_search,rowid,id,name,tags,payload,term_text) VALUES('delete',old.rowid,old.id,old.name,old.tags,old.payload,old.term_text);
END;
CREATE TRIGGER item_surface_search_update AFTER UPDATE ON item_surfaces BEGIN
 INSERT INTO item_surface_search(item_surface_search,rowid,id,name,tags,payload,term_text) VALUES('delete',old.rowid,old.id,old.name,old.tags,old.payload,old.term_text);
 INSERT INTO item_surface_search(rowid,id,name,tags,payload,term_text) VALUES(new.rowid,new.id,new.name,new.tags,new.payload,new.term_text);
END;
CREATE TRIGGER item_surface_tags_insert AFTER INSERT ON item_surfaces BEGIN INSERT INTO item_surface_tags SELECT new.id,value FROM json_each(new.tags); END;
CREATE TRIGGER item_surface_tags_update AFTER UPDATE OF tags ON item_surfaces BEGIN
 DELETE FROM item_surface_tags WHERE surface_id=old.id;
 INSERT INTO item_surface_tags SELECT new.id,value FROM json_each(new.tags);
END;
-- Live counts of single-choice values per collection and surface, kept by
-- triggers, so board columns count without reading every item. The row with
-- an empty field_key counts the surfaces themselves (items and folders).
CREATE TABLE group_counts(container_id TEXT NOT NULL,surface TEXT NOT NULL,field_key TEXT NOT NULL,value TEXT NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(container_id,surface,field_key,value)) WITHOUT ROWID;
CREATE TRIGGER group_counts_surface_insert AFTER INSERT ON item_surfaces BEGIN
 INSERT INTO group_counts VALUES(new.container_id,new.surface,'','',1) ON CONFLICT DO UPDATE SET count=count+1;
END;
CREATE TRIGGER group_counts_surface_delete AFTER DELETE ON item_surfaces BEGIN
 UPDATE group_counts SET count=count-1 WHERE container_id=old.container_id AND surface=old.surface AND field_key='' AND value='';
END;
CREATE TRIGGER group_counts_surface_update AFTER UPDATE OF container_id,surface ON item_surfaces WHEN old.container_id<>new.container_id OR old.surface<>new.surface BEGIN
 UPDATE group_counts SET count=count-1 WHERE container_id=old.container_id AND surface=old.surface AND field_key='' AND value='';
 INSERT INTO group_counts VALUES(new.container_id,new.surface,'','',1) ON CONFLICT DO UPDATE SET count=count+1;
END;
CREATE TRIGGER group_counts_value_insert AFTER INSERT ON field_values WHEN new.field_type='choice' AND new.ordinal=0 AND new.value_text IS NOT NULL BEGIN
 INSERT INTO group_counts VALUES(new.container_id,new.surface,new.field_key,new.value_text,1) ON CONFLICT DO UPDATE SET count=count+1;
END;
CREATE TRIGGER group_counts_value_delete AFTER DELETE ON field_values WHEN old.field_type='choice' AND old.ordinal=0 AND old.value_text IS NOT NULL BEGIN
 UPDATE group_counts SET count=count-1 WHERE container_id=old.container_id AND surface=old.surface AND field_key=old.field_key AND value=old.value_text;
 DELETE FROM group_counts WHERE container_id=old.container_id AND surface=old.surface AND field_key=old.field_key AND value=old.value_text AND count<=0;
END;
CREATE TRIGGER group_counts_value_update AFTER UPDATE ON field_values WHEN old.field_type='choice' OR new.field_type='choice' BEGIN
 UPDATE group_counts SET count=count-1 WHERE old.field_type='choice' AND old.ordinal=0 AND container_id=old.container_id AND surface=old.surface AND field_key=old.field_key AND value=old.value_text;
 DELETE FROM group_counts WHERE container_id=old.container_id AND surface=old.surface AND field_key=old.field_key AND value=old.value_text AND count<=0;
 INSERT INTO group_counts SELECT new.container_id,new.surface,new.field_key,new.value_text,1 WHERE new.field_type='choice' AND new.ordinal=0 AND new.value_text IS NOT NULL ON CONFLICT DO UPDATE SET count=count+1;
END;
CREATE TRIGGER schema_revision_validate BEFORE INSERT ON schema_revisions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM resources WHERE id=new.container_id AND kind IN ('list','library')) THEN RAISE(ABORT,'invalid schema container') END;
END;
CREATE TRIGGER schema_revision_immutable BEFORE UPDATE ON schema_revisions BEGIN SELECT RAISE(ABORT,'schema revision is immutable'); END;
CREATE TRIGGER schema_revision_retained BEFORE DELETE ON schema_revisions WHEN NOT EXISTS(SELECT 1 FROM resources c JOIN resources w ON w.id=c.workspace_id WHERE c.id=old.container_id AND w.personal_owner_id IS NOT NULL AND w.deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'schema revisions are retained'); END;
CREATE TRIGGER item_revision_validate BEFORE INSERT ON item_revisions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM resources WHERE id=new.item_id AND kind IN ('item','folder') AND container_id=new.container_id AND content_type_id=new.content_type_id)
 OR NOT EXISTS(SELECT 1 FROM schema_revisions s, json_each(s.definition,'$.content_types') t WHERE s.id=new.schema_revision_id AND json_extract(t.value,'$.id')=new.content_type_id)
 OR (new.blob_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM blobs WHERE id=new.blob_id AND item_id=new.item_id))
 THEN RAISE(ABORT,'invalid revision ownership') END;
END;
CREATE TRIGGER collection_type_validate BEFORE INSERT ON collection_types BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM resources WHERE id=new.container_id AND kind IN ('list','library')) THEN RAISE(ABORT,'invalid content type collection') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM collection_types a JOIN content_types t ON t.id=a.content_type_id JOIN content_types n ON n.id=new.content_type_id WHERE a.container_id=new.container_id AND t.key=n.key) THEN RAISE(ABORT,'duplicate collection content type key') END;
END;
CREATE TRIGGER collection_type_identity BEFORE UPDATE OF id,container_id,content_type_id ON collection_types BEGIN
 SELECT CASE WHEN new.id IS NOT old.id OR new.container_id IS NOT old.container_id OR new.content_type_id IS NOT old.content_type_id THEN RAISE(ABORT,'content type attachment identity is immutable') END;
END;
CREATE TRIGGER content_type_identity BEFORE UPDATE OF id,key ON content_types BEGIN
 SELECT CASE WHEN new.id IS NOT old.id OR new.key IS NOT old.key THEN RAISE(ABORT,'content type identity is immutable') END;
END;
CREATE TRIGGER business_key_validate BEFORE INSERT ON business_keys BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM resources WHERE id=new.item_id AND kind IN ('item','folder') AND container_id=new.container_id AND deleted_at IS NULL)
 THEN RAISE(ABORT,'invalid business key owner') END;
END;
CREATE TRIGGER business_key_immutable BEFORE UPDATE ON business_keys BEGIN SELECT RAISE(ABORT,'business key claims are immutable'); END;
CREATE TRIGGER item_revision_immutable BEFORE UPDATE ON item_revisions BEGIN SELECT RAISE(ABORT,'item revision is immutable'); END;
CREATE TRIGGER resource_revision_pointers BEFORE UPDATE OF head_revision_id,published_revision_id,schema_head_id,publishing_enabled,webdav_enabled ON resources BEGIN
 SELECT CASE WHEN (new.head_revision_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM item_revisions WHERE id=new.head_revision_id AND item_id=new.id))
 OR (new.published_revision_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM item_revisions WHERE id=new.published_revision_id AND item_id=new.id))
 OR (new.schema_head_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM schema_revisions WHERE id=new.schema_head_id AND container_id=new.id))
 OR (new.publishing_enabled AND new.kind NOT IN ('list','library')) OR (new.webdav_enabled AND new.kind<>'library')
 THEN RAISE(ABORT,'invalid revision pointer') END;
END;
CREATE TRIGGER publication_revision_validate BEFORE INSERT ON publications BEGIN
 SELECT CASE WHEN new.revision_id IS NULL OR new.action NOT IN ('publish','unpublish')
 THEN RAISE(ABORT,'invalid publication revision') END;
END;
CREATE TRIGGER publication_retained BEFORE DELETE ON publications WHEN NOT EXISTS(SELECT 1 FROM resources WHERE id=old.item_id AND deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'live publication events are retained'); END;
CREATE TRIGGER resource_revision_insert BEFORE INSERT ON resources BEGIN
 SELECT CASE WHEN new.head_revision_id IS NOT NULL OR new.published_revision_id IS NOT NULL OR new.schema_head_id IS NOT NULL
 OR (new.publishing_enabled AND new.kind NOT IN ('list','library')) OR (new.webdav_enabled AND new.kind<>'library')
 OR new.next_revision_number<>1 OR new.deleted_at IS NOT NULL
 THEN RAISE(ABORT,'invalid initial revision state') END;
END;
CREATE TRIGGER resource_revision_counter BEFORE UPDATE OF next_revision_number ON resources BEGIN
 SELECT CASE WHEN new.next_revision_number<old.next_revision_number OR new.next_revision_number<1 THEN RAISE(ABORT,'revision counter cannot decrease') END;
END;
CREATE TRIGGER field_identity_immutable BEFORE UPDATE OF key,type,scale ON field_definitions BEGIN
 SELECT CASE WHEN new.key IS NOT old.key OR new.type IS NOT old.type OR new.scale IS NOT old.scale
 THEN RAISE(ABORT,'field keys, types and scales are immutable') END;
END;
CREATE TRIGGER item_surface_validate_insert BEFORE INSERT ON item_surfaces BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM resources r JOIN item_revisions v ON v.id=new.revision_id WHERE r.id=new.item_id AND r.kind IN ('item','folder') AND r.container_id=new.container_id AND r.workspace_id=new.workspace_id AND v.item_id=r.id AND v.name=new.name AND v.tags=new.tags AND v.payload=new.payload)
 THEN RAISE(ABORT,'invalid surface projection') END;
END;
CREATE TRIGGER item_surface_validate_update BEFORE UPDATE ON item_surfaces BEGIN
 SELECT CASE WHEN new.item_id IS NOT old.item_id OR new.container_id IS NOT old.container_id OR new.workspace_id IS NOT old.workspace_id OR new.surface IS NOT old.surface
 OR NOT EXISTS(SELECT 1 FROM item_revisions WHERE id=new.revision_id AND item_id=new.item_id AND name=new.name AND tags=new.tags AND payload=new.payload)
 THEN RAISE(ABORT,'invalid surface projection') END;
END;
CREATE TRIGGER additive_grants_insert BEFORE INSERT ON grants BEGIN
 SELECT CASE WHEN new.effect<>'allow' OR new.action NOT IN ('read','read_draft','write','publish','manage') THEN RAISE(ABORT,'only additive grants are supported') END;
END;
CREATE TRIGGER additive_grants_update BEFORE UPDATE ON grants BEGIN
 SELECT CASE WHEN new.effect<>'allow' OR new.action NOT IN ('read','read_draft','write','publish','manage') THEN RAISE(ABORT,'only additive grants are supported') END;
END;
CREATE TRIGGER resource_permission_scope_validate BEFORE UPDATE OF inherit_permissions ON resources BEGIN
 SELECT CASE WHEN new.inherit_permissions AND (new.kind='workspace' OR EXISTS(SELECT 1 FROM grants WHERE resource_id=new.id)) THEN RAISE(ABORT,'inherited resources cannot contain grants') END;
END;
CREATE TRIGGER grant_exclusive_scope_insert BEFORE INSERT ON grants BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM resources WHERE id=new.resource_id AND inherit_permissions) THEN RAISE(ABORT,'grants require an exclusive permission scope') END;
END;
CREATE TRIGGER grant_exclusive_scope_update BEFORE UPDATE OF resource_id ON grants BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM resources WHERE id=new.resource_id AND inherit_permissions) THEN RAISE(ABORT,'grants require an exclusive permission scope') END;
END;
CREATE TRIGGER field_type_validate BEFORE INSERT ON field_definitions BEGIN
 SELECT CASE WHEN new.type NOT IN ('text','note','email','url','date','lookup','person','term','keywords','choice','datetime','integer','decimal','number','currency','boolean') OR new.scale<0 OR new.scale>9 OR (new.type<>'decimal' AND new.scale<>0) OR (coalesce(json_extract(new.options,'$.multiple'),0) AND new.type NOT IN ('choice','person','lookup','term','keywords'))
 THEN RAISE(ABORT,'invalid field type or scale') END;
END;
CREATE TRIGGER field_options_identity BEFORE UPDATE OF options ON field_definitions BEGIN
 SELECT CASE WHEN coalesce(json_extract(new.options,'$.multiple'),0)<>coalesce(json_extract(old.options,'$.multiple'),0)
 OR coalesce(json_extract(new.options,'$.lookup_container_id'),'')<>coalesce(json_extract(old.options,'$.lookup_container_id'),'')
 OR coalesce(json_extract(new.options,'$.term_set_id'),'')<>coalesce(json_extract(old.options,'$.term_set_id'),'')
 THEN RAISE(ABORT,'field cardinality and reference scope are immutable') END;
END;
CREATE TRIGGER field_value_validate BEFORE INSERT ON field_values BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM item_surfaces WHERE id=new.surface_id AND item_id=new.item_id AND container_id=new.container_id AND surface=new.surface)
 THEN RAISE(ABORT,'invalid field index ownership') END;
END;
CREATE TRIGGER field_value_no_update BEFORE UPDATE ON field_values BEGIN SELECT RAISE(ABORT,'replace derived field index rows'); END;
CREATE TRIGGER term_parent_validate BEFORE INSERT ON terms WHEN new.parent_id IS NOT NULL BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM terms WHERE id=new.parent_id AND term_set_id=new.term_set_id) THEN RAISE(ABORT,'term parent must belong to the same term set') END;
END;
CREATE TRIGGER term_parent_move_validate BEFORE UPDATE OF term_set_id,parent_id ON terms WHEN new.parent_id IS NOT NULL BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM terms WHERE id=new.parent_id AND term_set_id=new.term_set_id) THEN RAISE(ABORT,'term parent must belong to the same term set') END;
END;
CREATE TRIGGER term_retained BEFORE DELETE ON terms BEGIN SELECT RAISE(ABORT,'terms are retained; deprecate or merge them'); END;
CREATE TRIGGER term_groups_identity_immutable BEFORE UPDATE OF is_system ON term_groups BEGIN
 SELECT CASE WHEN new.is_system IS NOT old.is_system THEN RAISE(ABORT,'term group identity is immutable') END;
END;
CREATE TRIGGER listview_container_validate BEFORE INSERT ON list_views BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM resources WHERE id=new.container_id AND kind IN ('list','library')) THEN RAISE(ABORT,'view requires a collection') END;
END;
CREATE TRIGGER listview_container_immutable BEFORE UPDATE OF container_id ON list_views BEGIN
 SELECT CASE WHEN new.container_id IS NOT old.container_id THEN RAISE(ABORT,'view ownership is immutable') END;
END;
CREATE TRIGGER schema_templates_workspace_validate BEFORE INSERT ON schema_templates BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM resources WHERE id=new.workspace_id AND kind='workspace') THEN RAISE(ABORT,'configuration requires a workspace') END;
END;
CREATE TRIGGER schema_templates_identity_immutable BEFORE UPDATE OF workspace_id,key ON schema_templates BEGIN
 SELECT CASE WHEN new.workspace_id IS NOT old.workspace_id OR new.key IS NOT old.key THEN RAISE(ABORT,'configuration identity is immutable') END;
END;
CREATE TRIGGER term_sets_identity_immutable BEFORE UPDATE OF key,group_id,is_keywords ON term_sets BEGIN
 SELECT CASE WHEN new.key IS NOT old.key OR new.group_id IS NOT old.group_id OR new.is_keywords IS NOT old.is_keywords THEN RAISE(ABORT,'configuration identity is immutable') END;
END;
CREATE TRIGGER relationship_types_term_validate BEFORE INSERT ON relationship_types BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM terms t JOIN term_sets s ON s.id=t.term_set_id WHERE t.id=new.id AND s.key='relationship_types' AND t.deprecated=0 AND t.merged_into_id IS NULL) THEN RAISE(ABORT,'relationship type requires an active predicate term') END;
END;
CREATE TRIGGER relationship_type_validate BEFORE INSERT ON relationships BEGIN
 SELECT CASE WHEN (new.type_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM relationship_types p JOIN terms t ON t.id=p.id WHERE p.id=new.type_id AND p.directed=new.directed AND t.deprecated=0 AND t.merged_into_id IS NULL))
 OR (new.directed=0 AND new.source_id>=new.target_id) THEN RAISE(ABORT,'invalid typed relationship') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM relationship_types t WHERE t.id=new.type_id AND
 ((t.max_outgoing IS NOT NULL AND (SELECT count(*) FROM relationships WHERE type_id=t.id AND source_id=new.source_id)>=t.max_outgoing)
 OR (t.max_incoming IS NOT NULL AND (SELECT count(*) FROM relationships WHERE type_id=t.id AND target_id=new.target_id)>=t.max_incoming)))
 THEN RAISE(ABORT,'relationship cardinality exceeded') END;
END;
CREATE TRIGGER relationship_type_identity BEFORE UPDATE OF type_id,directed ON relationships BEGIN
 SELECT CASE WHEN new.type_id IS NOT old.type_id OR new.directed IS NOT old.directed THEN RAISE(ABORT,'relationship type and direction are immutable') END;
END;
CREATE TRIGGER relationship_policy_identity BEFORE UPDATE OF directed ON relationship_types BEGIN
 SELECT CASE WHEN new.directed IS NOT old.directed THEN RAISE(ABORT,'relationship policy identity is immutable') END;
END;

CREATE INDEX itemsurface_container_id_surface_modified_at_item_id ON item_surfaces(container_id,surface,modified_at,item_id);

CREATE INDEX itemsurface_container_id_surface_modified_by_item_id ON item_surfaces(container_id,surface,modified_by,item_id);

CREATE INDEX itemsurface_container_id_surface_item_created_at_item_id ON item_surfaces(container_id,surface,item_created_at,item_id);

CREATE INDEX itemsurface_container_id_surface_item_created_by_item_id ON item_surfaces(container_id,surface,item_created_by,item_id);

CREATE INDEX itemsurface_container_id_surface_name_item_id ON item_surfaces(container_id,surface,name,item_id);

CREATE TRIGGER workflow_validate BEFORE INSERT ON workflows BEGIN
 SELECT RAISE(ABORT,'workflow workspace must be a workspace') WHERE NOT EXISTS(SELECT 1 FROM resources WHERE id=new.workspace_id AND kind='workspace');
 SELECT RAISE(ABORT,'workflow collection must be a list or library of its workspace') WHERE new.collection_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM resources WHERE id=new.collection_id AND workspace_id=new.workspace_id AND kind IN ('list','library'));
END;
CREATE TRIGGER workflow_identity BEFORE UPDATE OF id,workspace_id,key,builtin_key,collection_id,created_by ON workflows BEGIN SELECT RAISE(ABORT,'workflow identity is immutable'); END;
CREATE TRIGGER workflow_tombstone BEFORE UPDATE ON workflows WHEN old.deleted_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'deleted workflows are final'); END;
CREATE TRIGGER workflow_retained BEFORE DELETE ON workflows WHEN NOT EXISTS(SELECT 1 FROM resources WHERE id=old.workspace_id AND personal_owner_id IS NOT NULL AND deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'workflows are retained; delete sets deleted_at'); END;
CREATE TRIGGER domain_event_immutable BEFORE UPDATE OF id,created_at,type,workspace_id,collection_id,resource_id,actor,data,depth,cause_run_id ON domain_events BEGIN SELECT RAISE(ABORT,'domain events are immutable'); END;
CREATE TRIGGER workflow_version_immutable BEFORE UPDATE ON workflow_versions BEGIN SELECT RAISE(ABORT,'workflow versions are immutable'); END;
CREATE TRIGGER workflow_version_retained BEFORE DELETE ON workflow_versions WHEN NOT EXISTS(SELECT 1 FROM workflows f JOIN resources w ON w.id=f.workspace_id WHERE f.id=old.workflow_id AND w.personal_owner_id IS NOT NULL AND w.deleted_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'workflow versions are retained'); END;
CREATE TRIGGER workflow_run_immutable BEFORE UPDATE OF id,created_at,workflow_id,workflow_version,item_id,event_id,event_type,depth,actor,retry_of ON workflow_runs BEGIN SELECT RAISE(ABORT,'workflow run identity and inputs are immutable'); END;
CREATE TRIGGER workflow_run_item_immutable BEFORE UPDATE ON workflow_run_items BEGIN SELECT RAISE(ABORT,'run membership is immutable'); END;

-- Workspace members are canonical root grants: one role per authenticated subject.
-- Role capabilities: owner=manage, member=write, visitor=read.
CREATE TRIGGER workspace_member_insert BEFORE INSERT ON grants
WHEN EXISTS(SELECT 1 FROM resources WHERE id=new.resource_id AND kind='workspace') BEGIN
 SELECT CASE WHEN new.principal_type<>'user' OR new.action NOT IN ('manage','write','read') OR length(trim(new.principal_id))=0 OR new.principal_id<>trim(new.principal_id)
 OR EXISTS(SELECT 1 FROM grants WHERE resource_id=new.resource_id AND principal_id=new.principal_id)
 THEN RAISE(ABORT,'invalid workspace membership') END;
END;
CREATE TRIGGER workspace_member_update BEFORE UPDATE ON grants
WHEN EXISTS(SELECT 1 FROM resources WHERE id IN (old.resource_id,new.resource_id) AND kind='workspace') BEGIN
 SELECT CASE WHEN new.resource_id IS NOT old.resource_id OR new.principal_type IS NOT old.principal_type OR new.principal_id IS NOT old.principal_id OR new.action NOT IN ('manage','write','read')
 THEN RAISE(ABORT,'invalid workspace membership') END;
 SELECT CASE WHEN old.action='manage' AND new.action<>'manage'
 AND EXISTS(SELECT 1 FROM resources WHERE id=old.resource_id AND deleted_at IS NULL)
 AND NOT EXISTS(SELECT 1 FROM grants WHERE resource_id=old.resource_id AND principal_id<>old.principal_id AND action='manage')
 THEN RAISE(ABORT,'a workspace needs at least one owner') END;
END;
CREATE TRIGGER workspace_last_owner_delete BEFORE DELETE ON grants
WHEN old.action='manage' AND EXISTS(SELECT 1 FROM resources WHERE id=old.resource_id AND kind='workspace' AND deleted_at IS NULL) BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM grants WHERE resource_id=old.resource_id AND principal_id<>old.principal_id AND action='manage')
 THEN RAISE(ABORT,'a workspace needs at least one owner') END;
END;

-- Organization identity, directory, nested groups and module-scoped roles.
CREATE TABLE identity_organizations (id TEXT NOT NULL PRIMARY KEY, created_at DATETIME NOT NULL, singleton BOOLEAN NOT NULL DEFAULT 1 CHECK(singleton=1), identifier TEXT NOT NULL CHECK(length(identifier) BETWEEN 1 AND 128), display_name TEXT NOT NULL CHECK(length(display_name) BETWEEN 1 AND 200), description TEXT NOT NULL DEFAULT '' CHECK(length(description)<=2000), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE UNIQUE INDEX identityorganization_singleton ON identity_organizations(singleton);
CREATE TABLE identity_users (id TEXT NOT NULL PRIMARY KEY CHECK(length(id) BETWEEN 1 AND 255 AND id=trim(id)), created_at datetime NOT NULL, active BOOLEAN NOT NULL DEFAULT 1 CHECK(active IN (0,1)), display_name TEXT NOT NULL DEFAULT '' CHECK(length(display_name)<=200), email TEXT NOT NULL DEFAULT '' CHECK(length(email)<=256), sync_hash TEXT NOT NULL DEFAULT '', deleted_at DATETIME, CHECK(deleted_at IS NULL OR (active=0 AND display_name='Deleted user' AND email='')));
CREATE TABLE identity_rest_tokens(id TEXT NOT NULL PRIMARY KEY,created_at DATETIME NOT NULL,subject TEXT NOT NULL REFERENCES identity_users(id),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 200),prefix TEXT NOT NULL,secret_hash TEXT NOT NULL CHECK(length(secret_hash)=64),scopes JSON NOT NULL CHECK(json_valid(scopes) AND json_type(scopes)='array' AND json_array_length(scopes)>0),expires_at DATETIME NOT NULL,last_used_at DATETIME,revoked_at DATETIME);
CREATE UNIQUE INDEX identityresttoken_secret_hash ON identity_rest_tokens(secret_hash);
CREATE INDEX identityresttoken_subject_id ON identity_rest_tokens(subject,id);
CREATE TABLE identity_groups (id TEXT NOT NULL PRIMARY KEY, created_at datetime NOT NULL, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 200), description TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT 'local' CHECK(source IN ('local','oidc')), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE UNIQUE INDEX identitygroup_name ON identity_groups(name);
CREATE TABLE identity_roles (id TEXT NOT NULL PRIMARY KEY, created_at datetime NOT NULL, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 200), description TEXT NOT NULL DEFAULT '', scopes JSON NOT NULL DEFAULT '[]' CHECK(json_valid(scopes) AND json_type(scopes)='array'), builtin bool NOT NULL DEFAULT false, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE UNIQUE INDEX identityrole_name ON identity_roles(name);
CREATE TABLE identity_memberships (id TEXT NOT NULL PRIMARY KEY, created_at datetime NOT NULL, group_id TEXT NOT NULL REFERENCES identity_groups(id) ON DELETE CASCADE, principal_type TEXT NOT NULL CHECK(principal_type IN ('user','group')), principal_id TEXT NOT NULL);
CREATE UNIQUE INDEX identitymembership_group_id_principal_type_principal_id ON identity_memberships(group_id,principal_type,principal_id);
CREATE INDEX identitymembership_principal_type_principal_id_group_id ON identity_memberships(principal_type,principal_id,group_id);
CREATE TABLE identity_assignments (id TEXT NOT NULL PRIMARY KEY, created_at datetime NOT NULL, role_id TEXT NOT NULL REFERENCES identity_roles(id) ON DELETE CASCADE, principal_type TEXT NOT NULL CHECK(principal_type IN ('user','group')), principal_id TEXT NOT NULL);
CREATE UNIQUE INDEX identityassignment_role_id_principal_type_principal_id ON identity_assignments(role_id,principal_type,principal_id);
CREATE INDEX identityassignment_principal_type_principal_id_role_id ON identity_assignments(principal_type,principal_id,role_id);
CREATE TRIGGER identity_membership_principal BEFORE INSERT ON identity_memberships BEGIN
 SELECT CASE WHEN (new.principal_type='user' AND NOT EXISTS(SELECT 1 FROM identity_users WHERE id=new.principal_id)) OR (new.principal_type='group' AND NOT EXISTS(SELECT 1 FROM identity_groups WHERE id=new.principal_id)) THEN RAISE(ABORT,'unknown group member') END;
END;
CREATE TRIGGER identity_assignment_principal BEFORE INSERT ON identity_assignments BEGIN
 SELECT CASE WHEN (new.principal_type='user' AND NOT EXISTS(SELECT 1 FROM identity_users WHERE id=new.principal_id)) OR (new.principal_type='group' AND NOT EXISTS(SELECT 1 FROM identity_groups WHERE id=new.principal_id)) THEN RAISE(ABORT,'unknown role principal') END;
END;
CREATE TRIGGER identity_membership_immutable BEFORE UPDATE ON identity_memberships BEGIN SELECT RAISE(ABORT,'replace group memberships instead of updating them'); END;
CREATE TRIGGER identity_assignment_immutable BEFORE UPDATE ON identity_assignments BEGIN SELECT RAISE(ABORT,'replace role assignments instead of updating them'); END;
CREATE TRIGGER identity_group_delete AFTER DELETE ON identity_groups BEGIN
 DELETE FROM identity_memberships WHERE principal_type='group' AND principal_id=old.id;
 DELETE FROM identity_assignments WHERE principal_type='group' AND principal_id=old.id;
 DELETE FROM grants WHERE principal_type='group' AND principal_id=old.id;
END;
CREATE TRIGGER identity_user_delete AFTER DELETE ON identity_users BEGIN
 DELETE FROM identity_memberships WHERE principal_type='user' AND principal_id=old.id;
 DELETE FROM identity_assignments WHERE principal_type='user' AND principal_id=old.id;
END;
CREATE TRIGGER identity_builtin_role_update BEFORE UPDATE ON identity_roles WHEN old.builtin=1 BEGIN SELECT RAISE(ABORT,'built-in roles are immutable'); END;
CREATE TRIGGER identity_builtin_role_delete BEFORE DELETE ON identity_roles WHEN old.builtin=1 BEGIN SELECT RAISE(ABORT,'built-in roles cannot be deleted'); END;
CREATE TRIGGER grant_principal_insert BEFORE INSERT ON grants BEGIN
 SELECT CASE WHEN (new.principal_type='user' AND NOT EXISTS(SELECT 1 FROM identity_users WHERE id=new.principal_id)) OR (new.principal_type='group' AND NOT EXISTS(SELECT 1 FROM identity_groups WHERE id=new.principal_id)) OR (new.principal_type IN ('workspace_visitor','workspace_member','workspace_owner') AND NOT EXISTS(SELECT 1 FROM resources WHERE id=new.resource_id AND workspace_id=new.principal_id)) OR (new.principal_type='workspace_owner' AND new.action<>'manage') THEN RAISE(ABORT,'invalid ACL principal') END;
END;
CREATE TRIGGER grant_principal_update BEFORE UPDATE OF principal_type,principal_id,action ON grants BEGIN
 SELECT CASE WHEN (new.principal_type='user' AND NOT EXISTS(SELECT 1 FROM identity_users WHERE id=new.principal_id)) OR (new.principal_type='group' AND NOT EXISTS(SELECT 1 FROM identity_groups WHERE id=new.principal_id)) OR (new.principal_type IN ('workspace_visitor','workspace_member','workspace_owner') AND NOT EXISTS(SELECT 1 FROM resources WHERE id=new.resource_id AND workspace_id=new.principal_id)) OR (new.principal_type='workspace_owner' AND new.action<>'manage') THEN RAISE(ABORT,'invalid ACL principal') END;
END;

